def movement_line(move: Movement) -> str:
    return "%s %s %+d%s" % (move.date.isoformat(), move.sku, move.quantity, " " + move.note if move.note else "")


def append_movements(data: Data, new: Sequence[Movement]) -> None:
    """Validate the movements against the file, then append them (all or nothing)."""
    text = "".join(movement_line(m) + "\n" for m in new)
    try:
        payload = text.encode("utf-8")
    except UnicodeEncodeError:
        raise CliError(1, "note cannot be written as UTF-8") from None
    try:
        validate_movements(list(data.movements) + list(new))
    except ParseError as exc:
        raise CliError(1, "%s: %s" % (MOVEMENTS, exc)) from None
    if data.movements_raw and not data.movements_raw.endswith(b"\n"):
        payload = b"\n" + payload
    try:
        with open(data.movements_path, "ab") as handle:
            handle.write(payload)
    except OSError as exc:
        raise CliError(2, "%s: cannot write (%s)" % (MOVEMENTS, exc.strerror or exc)) from None


def next_line_number(data: Data) -> int:
    raw = data.movements_raw
    count = raw.count(b"\n")
    return count + 1 if not raw or raw.endswith(b"\n") else count + 2

